export function getMsgHdrsForIndex(dbView, idx, includeCollapsedThreads) {
  if (
    includeCollapsedThreads &&
    dbView.isContainer(idx) &&
    !dbView.isContainerOpen(idx)
  ) {
    const thread = dbView.getThreadContainingIndex(idx);
    const children = [];
    for (let i = 0; i < thread.numChildren; i++) {
      children.push(thread.getChildHdrAt(i));
    }
    return children;
  }
  return [dbView.getMsgHdrAt(idx)];

if (!about3PaneWindow.threadTree._selection._selectEventsSuppressed) {
  return selectedIndices.flatMap(idx =>
    getMsgHdrsForIndex(dbView, idx, true)
  );
}

// Get the indices, which are considered to be invalid by the UI, which
// includes *all* selected indices, if the UI is suppressing the selection.
// Filter out the indices we are not interested in.
const invalidIndices = [
  ...about3PaneWindow.threadTree._selection._invalidIndices,
];
return invalidIndices
  .filter(idx => !selectedIndices.includes(idx))
  .flatMap(idx => getMsgHdrsForIndex(dbView, idx, true));

} else if (event.type == "select") {
  if (targetWindow?.gDBView) {
    const messages = getActualSelectedMessages(targetWindow);
    this.emit("messages-changed", tab, messages);
  }

function getDisplayedMessages(tab) {
  const nativeTab = tab.nativeTab;
  if (tab instanceof TabmailTab) {
    if (nativeTab.mode.name == "mail3PaneTab") {
      return getActualSelectedMessages(nativeTab.chromeBrowser.contentWindow);
    } else if (nativeTab.mode.name == "mailMessageTab") {
      return [nativeTab.chromeBrowser.contentWindow.gMessage];
    }
  } else if (nativeTab?.messageBrowser) {
    return [nativeTab.messageBrowser.contentWindow.gMessage];
  }
  return [];
